function createCredential(config: ServicePrincipalConfig): ClientSecretCredential {
  return new ClientSecretCredential(
    config.tenantId,
    config.clientId,
    config.clientSecret,
    {
      // Optional: configure retry and logging
      retryOptions: {
        maxRetries: 3,
        retryDelayInMs: 800,
        maxRetryDelayInMs: 6400,
      },
    }
  );
}

// ---------------------------------------------------------------------------
