      console.log(`     - Content Type: ${blob.properties.contentType}`);
      console.log(`     - Last Modified: ${blob.properties.lastModified}`);
    }
    
    console.log(`   ✓ Total blobs: ${blobCount}\n`);

    // 5. Download the blob and print its content
