+    console.log("7. Deleting setting: app:Settings:FontSize");
+    await client.deleteConfigurationSetting({
+      key: "app:Settings:FontSize"
+    });
+    console.log("✓ Setting deleted\n");
+
+    // Cleanup: Delete other test settings
